//! C ABI over `nimk-engine` for the Swift IMK shim.
//!
//! The only crate allowed to use `unsafe` and `extern "C"`. Every exported
//! function catches panics and degrades to "pass the key through".
//! The header `nimk_ffi.h` is generated by cbindgen (see `cbindgen.toml`).
//!
//! Ownership rules:
//! - `NimkCore` is created by `nimk_new` and destroyed by `nimk_shutdown`
//!   or `nimk_free`; it must only be used from the IMK main thread.
//! - Strings returned in `NimkOut` (and by `nimk_take_diagnostics` /
//!   `nimk_policy_id`) are owned by the core and live until the next call of
//!   the same kind; Swift copies them immediately.

// The workspace denies `unsafe_code`; this crate is the single, audited
// exception because a C ABI cannot be expressed without it. Every `unsafe`
// block carries a SAFETY comment.
#![allow(unsafe_code)]

mod abi;
mod exports;
mod handle;

pub use abi::{
    NIMK_KIND_FLAGS_CHANGED, NIMK_KIND_KEY_DOWN, NIMK_MODE_EN, NIMK_MODE_UNCHANGED, NIMK_MODE_VI,
    NIMK_OVERLAY_AUTO, NIMK_OVERLAY_MANUAL, NIMK_OVERLAY_NONE, NimkCtx, NimkKey, NimkModelStats,
    NimkOut,
};
pub use exports::{
    nimk_commit_pending, nimk_context, nimk_free, nimk_hook_summary, nimk_idle_commit_secs,
    nimk_key, nimk_mode, nimk_new, nimk_note_navigation, nimk_note_wall_clock, nimk_policy_id,
    nimk_set_config, nimk_shutdown, nimk_take_diagnostics,
};
pub use handle::NimkCore;
